  private void Message(string s){if(status)status.text=s;}
  private void Begin(IEnumerator operation){if(busy)return;StartCoroutine(Run(operation));}
  private IEnumerator Run(IEnumerator operation){busy=true;EnableUi();try{yield return operation;}finally{busy=false;EnableUi();Actions();}}
  private void EnableUi(){foreach(var g in groups)g.interactable=!busy&&!dialog;if(dialogGroup)dialogGroup.interactable=!busy;if(model)model.enabled=!busy&&!dialog;}
  private bool Failed<T>(ApiResult<T> r){if(r!=null&&r.Ok)return false;Message(r?.Message??"No se pudo completar la operación.");return true;}
  private void Login(){if(busy||dialog)return;if(!ApiProtocol.TryBaseUrl(server.text,out var url,out var error)){Message(error);return;}if(string.IsNullOrWhiteSpace(email.text)||string.IsNullOrEmpty(password.text)){Message("Ingresa correo y contraseña.");return;}api.Configure(url);var body=new LoginData{correo=email.text.Trim(),password=password.text};password.SetTextWithoutNotify("");QuestKeyboard.Close();Begin(Authenticate(body));}
  private IEnumerator Authenticate(LoginData body){Message("Conectando…");ApiResult<TokenData> t=null;yield return api.Send<TokenData>("POST","/auth/login",body,r=>t=r,false);body.password=null;if(Failed(t))yield break;bool valid=true;try{api.Authenticate(t.Data);}catch(Exception){valid=false;}if(!valid){api.ClearSession();Message("No se pudo iniciar sesión.");yield break;}ApiResult<Usuario> u=null;yield return api.Send<Usuario>("GET","/auth/me",null,r=>u=r);if(Failed(u))yield break;if(u.Data?.rol!="medico"||!u.Data.activo){api.ClearSession();Message("Usa una cuenta de médico.");yield break;}api.SetUser(u.Data);username.text=u.Data.nombre;login.gameObject.SetActive(false);listBox.gameObject.SetActive(true);page=1;filter="listo";yield return LoadList();}
  private void Filter(string state){if(busy||dialog)return;filter=state;page=1;Begin(LoadList());}
