  private IEnumerator Take(){if(!ApiProtocol.CanTake(selected,api.User))yield break;int id=selected.id;ApiResult<Consulta> r=null;yield return api.Send<Consulta>("PATCH","/consultas/"+id+"/estado",new EstadoData{estado="en_atencion"},x=>r=x);if(Failed(r))yield break;yield return Load(id);}
  private IEnumerator SaveNote(){if(!Writable||string.IsNullOrWhiteSpace(noteInput.text))yield break;ApiResult<Nota> r=null;object body=note==null?(object)new NotaData{contenido=noteInput.text.Trim()}:new NotaActualizarData{contenido=noteInput.text.Trim(),version_esperada=note.version};yield return api.Send<Nota>(note==null?"POST":"PUT","/consultas/"+selected.id+"/nota",body,x=>r=x);if(Failed(r))yield break;note=r.Data;noteInput.SetTextWithoutNotify(note.contenido);Actions();Message("Nota guardada · Versión "+note.version);}
