  private IEnumerator Close(){if(!Writable||note==null||Dirty)yield break;int id=selected.id;ApiResult<Consulta> r=null;yield return api.Send<Consulta>("PATCH","/consultas/"+id+"/estado",new EstadoData{estado="cerrado"},x=>r=x);if(Failed(r))yield break;call.End();selected=r.Data;Render();Message("Consulta cerrada.");}
